+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Snake Game</title>
+    <style>
+        body {
+            background: rgba(15, 23, 42, 0.8);
+            backdrop-filter: blur(20px);
+            font-family: 'Inter', sans-serif;
+        }
+        .game-container {
+            max-width: 600px;
+            padding: 28px;
+            border-radius: 20px;
+            display: flex;
+            flex-direction: column;
+            align-items: center;
+            justify-content: center;
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.35);
+        }
+        .game-canvas {
+            border: 1px solid #fff;
+            border-radius: 10px;
+        }
+        .score {
+            font-size: 24px;
+            font-weight: bold;
+            color: #F8FAFC;
+            margin-bottom: 20px;
+        }
+        .high-score {
+            font-size: 18px;
+            color: #F8FAFC;
+            margin-bottom: 20px;
+        }
+        .start-game {
+            background: #0F172A;
+            color: #F8FAFC;
+            border: none;
+            padding: 10px 20px;
+            font-size: 18px;
+            cursor: pointer;
+            border-radius: 10px;
+        }
+        .start-game:hover {
+            background: #1A2336;
+        }
+    </style>
+</head>
+<body>
+    <div class="game-container">
+        <canvas id="game-canvas" width="400" height="400" class="game-canvas"></canvas>
+        <div class="score" id="score">Score: 0</div>
+        <div class="high-score" id="high-score">High Score: 0</div>
+        <button class="start-game" id="start-game">Start Game</button>
+    </div>
+    <script>
+        const canvas = document.getElementById('game-canvas');
+        const ctx = canvas.getContext('2d');
+        const scoreElement = document.getElementById('score');
+        const highScoreElement = document.getElementById('high-score');
+        const startGameButton = document.getElementById('start-game');
+        let score = 0;
+        let highScore = localStorage.getItem('highScore') || 0;
+        let snake = [
+            { x: 200, y: 200 },
+            { x: 190, y: 200 },
+            { x: 180, y: 200 }
+        ];
+        let direction = 'right';
+        let food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+        let intervalId;
+        startGameButton.addEventListener('click', startGame);
+        document.addEventListener('keydown', (e) => {
+            if (e.key === 'ArrowUp' && direction !== 'down') {
+                direction = 'up';
+            } else if (e.key === 'ArrowDown' && direction !== 'up') {
+                direction = 'down';
+            } else if (e.key === 'ArrowLeft' && direction !== 'right') {
+                direction = 'left';
+            } else if (e.key === 'ArrowRight' && direction !== 'left') {
+                direction = 'right';
+            }
+        });
+        function startGame() {
+            score = 0;
+            snake = [
+                { x: 200, y: 200 },
+                { x: 190, y: 200 },
+                { x: 180, y: 200 }
+            ];
+            direction = 'right';
+            food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+            intervalId = setInterval(draw, 100);
+            startGameButton.style.display = 'none';
+        }
+        function draw() {
+            ctx.clearRect(0, 0, canvas.width, canvas.height);
+            for (let i = 0; i < snake.length; i++) {
+                ctx.fillStyle = 'rgba(56, 189, 248, 0.5)';
+                ctx.fillRect(snake[i].x, snake[i].y, 10, 10);
+            }
+            ctx.fillStyle = 'rgba(255, 0, 0, 0.5)';
+            ctx.fillRect(food.x, food.y, 10, 10);
+            scoreElement.textContent = `Score: ${score}`;
+            highScoreElement.textContent = `High Score: ${highScore}`;
+            moveSnake();
+            checkCollision();
+        }
+        function moveSnake() {
+            let head = { x: snake[0].x, y: snake[0].y };
+            if (direction === 'up') {
+                head.y -= 10;
+            } else if (direction === 'down') {
+                head.y += 10;
+            } else if (direction === 'left') {
+                head.x -= 10;
+            } else if (direction === 'right') {
+                head.x += 10;
+            }
+            snake.unshift(head);
+            if (snake[0].x === food.x && snake[0].y === food.y) {
+                score++;
+                food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+            } else {
+                snake.pop();
+            }
+        }
+        function checkCollision() {
+            if (snake[0].x < 0 || snake[0].x >= canvas.width || snake[0].y < 0 || snake[0].y >= canvas.height) {
+                gameOver();
+            }
+            for (let i = 1; i < snake.length; i++) {
+                if (snake[0].x === snake[i].x && snake[0].y === snake[i].y) {
+                    gameOver();
+                }
+            }
+        }
+        function gameOver() {
+            clearInterval(intervalId);
+            if (score > highScore) {
+                highScore = score;
+                localStorage.setItem('highScore', highScore);
+            }
+            startGameButton.style.display = 'block';
+        }
+    </script>
+</body>
+</html>

